/* Presentation only: all numerical results come from ReportEngine's result contract. */
function feedbackValue(label,value){return `<div><span>${esc(label)}</span><strong>${value}</strong></div>`}
function feedbackSource(source){if(!source)return 'Origem pendente';let url;try{const u=new URL(source.url);if(['https:','http:'].includes(u.protocol))url=u.href}catch{}return `${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source.reference)}</a>`:esc(source.reference)} · ${source.kind==='product'?'premissa de produto':'base documental; aplicabilidade a confirmar'}`}
function feedbackRows(c){if(c.calculationStatus==='pending_rules')return '<p>Resultados pendentes de regras essenciais revisadas. Área e perímetro do terreno permanecem disponíveis.</p>';if(c.calculationStatus==='identification_only')return '<p>Zona sem cobertura: unidades e áreas construídas não calculadas.</p>';return `<table class="compare-table"><thead><tr><th>Pavimento</th><th>Laje</th><th>Largura</th><th>Núcleo</th><th>Privativa</th><th>UH por área</th></tr></thead><tbody>${c.floorPlates.map(p=>`<tr><td>${p.floor===1?'1 · térreo':p.floor}</td><td>${number(p.area,2)} m²</td><td>${number(p.width,2)} m</td><td>${number(p.coreArea,2)} m²</td><td>${number(p.privateArea,2)} m²</td><td>${number(p.units)}${p.eligible?'':' · lâmina insuficiente'}</td></tr>`).join('')}</tbody></table>`}
function feedbackParking(c){const p=c.parkingRules;if(c.calculationStatus==='pending_rules')return `<p>Exigência legal de vagas, meta do produto e compatibilidade com unidades permanecem pendentes de regras e projeto.</p><p>Capacidade informada no estudo: ${number(p.capacity)} vagas. ${p.layoutReference?esc(p.layoutReference):'Projeto de implantação pendente.'}</p>`;return `<div class="report-keyvalues">${feedbackValue('Mínimo legal',number(p.legalMinimum)+' vagas')}${feedbackValue('Meta do produto · 1 por UH',number(p.productTarget)+' vagas')}${feedbackValue('Capacidade física demonstrada',p.capacity===null?'Pendente':number(p.capacity)+' vagas')}</div><p>${feedbackSource(p.source)}</p><p>${number(p.directFrontageIllustration)} acessos diretos ilustrativos pela testada. ${esc(p.frontageAssumption)} ${p.layoutReference?'Referência informada: '+esc(p.layoutReference):'Circulação, manobras, acessibilidade e área de garagem ainda sem projeto.'}</p><p>As ${number(c.units)} unidades são uma estimativa por área privativa. A quantidade final depende da compatibilização com as vagas e o projeto.</p>`}
function feedbackNoteB(c){const n=c.noteB;if(!n)return '';if(!n.result)return `<p>${esc(n.message)}</p>`;const b=n.result;return `<table class="compare-table"><thead><tr><th>Hipótese</th><th>Pav.</th><th>TO / TAP</th><th>UH por área</th><th>Vagas mín. / meta</th><th>Equipamentos</th></tr></thead><tbody>${[[c,'Cenário atual'],[b,'Nota B · condicional']].map(([r,name])=>`<tr><td>${name}</td><td>${r.floors}</td><td>${number(Math.min(r.requestedOccupancy,r.toMax))}% / ${number(r.permeability)}%</td><td>${number(r.units)}</td><td>${number(r.parkingRules.legalMinimum)} / ${number(r.parkingRules.productTarget)}</td><td>${r.equipment.elevator.required?'Elevador + gerador':'Até 4 pavimentos'}</td></tr>`).join('')}</tbody></table><p>${feedbackSource(n.source)}. Aplicação condicionada a H3, via local/coletora e demais restrições. A comparação não define o melhor cenário; vagas, uso, alinhamento e custos precisam ser demonstrados.</p>`}
function feedbackFinancialTable(c){if(c.calculationStatus==='pending_rules')return '<p>Resultados pendentes de regras essenciais revisadas. Área e perímetro do terreno permanecem disponíveis.</p>';if(c.calculationStatus==='identification_only')return '<p>Viabilidade não calculada: zona fora da cobertura do motor demonstrativo.</p>';return `<table class="compare-table"><thead><tr><th>Componente</th><th>Valor</th></tr></thead><tbody>${c.financial.items.map(([name,value])=>`<tr><td>${esc(name)}</td><td>${money(value)}</td></tr>`).join('')}<tr><td>Total sem terreno</td><td>${money(c.nonLand)}</td></tr><tr><td>Residual estático com ITBI</td><td>${money(c.financial.residualStatic)}</td></tr><tr><td>Residual a valor presente com ITBI</td><td>${money(c.financial.residualNPV)}</td></tr></tbody></table><p>Hipóteses financeiras do feedback: ITBI 3% sobre aquisição, RET 4% e indiretos 10% do VGV, administração 12% da obra. Confirmar enquadramento fiscal. Projetos: maior entre 3% da obra e o piso informado. Cronograma hipotético: obra em ${c.financial.constructionMonths} meses; vendas em ${c.financial.salesMonths} meses a partir do mês ${c.financial.salesStartMonth}. Lucro alvo de ${number(state.profit)}% do VGV distribuído com as vendas.</p><p>TMA: ${c.financial.discount?`${number(c.financial.discount.annualRate*100,2)}% a.a. · ${esc(c.financial.discount.date)} · ${esc(c.financial.discount.source)}`:'Selic não informada; valor presente pendente'}. ${esc(c.financial.priceBasis)}. ${esc(c.financial.costBasis)}.</p>`}
function feedbackItem(p){const names={'essential-rules':'Regras essenciais',height:'Altura e gabarito','zone-conflict':'Conflito de zoneamento','note-b':'Condições da nota B',selic:'TMA / Selic',market:'Mercado e tributação',coastal:'Orla',use:'Permissão de uso',equipment:'Equipamentos',parking:'Projeto de vagas',macrozone:'Macrozona',zone:'Cobertura da zona',corner:'Esquina',balcony:'Varandas',setbacks:'Recuos','outorga-regulation':'Regulamentação de OODC','road-conflict':'Hierarquia viária'};const states={pending:'Pendente',informed:'Informado',special_review:'Revisão especial',incompatible:'Incompatível'};return `${names[p.id]||p.id.replace(/^cost-/, 'Orçamento · ')} · ${states[p.status]||p.status}`}
function feedbackPendings(c){return `<table class="compare-table"><thead><tr><th>Item / situação</th><th>Evidência e condição</th></tr></thead><tbody>${c.pendings.map(p=>`<tr><td>${esc(feedbackItem(p))}</td><td>${esc(p.message)}<br><small>${feedbackSource(p.source)}</small></td></tr>`).join('')}</tbody></table>`}
function feedbackReportView(c){const l=state.lot;return `<div class="report-layout"><article class="report-paper" id="report-paper"><div class="report-letterhead"><span class="report-logo"><span class="brand-art"><img src="./assets/viabileasy-logo.png" alt="ViabilEasy" width="560" height="180"></span></span><small>INTELIGÊNCIA URBANÍSTICA<br>${c.engine.demonstration?'ESTUDO DEMONSTRATIVO':'ESTUDO COM PENDÊNCIAS'} · ${esc(l.id)}</small></div><h2>Estudo de potencial construtivo</h2><p>Execução: ${esc(c.calculationStatus==='pending_rules'?'Resultados normativos pendentes':c.engine.execution==='server-demonstration'?'Servidor · demonstrativo':'Prévia local · demonstrativa')} · versão ${esc(c.engine.version)}. ${typeof EngineResults!=='undefined'&&EngineResults.error?esc(EngineResults.error):''}</p><p>${esc(l.name)} · João Pessoa/PB · ${number(l.area)} m²</p><div class="report-watermark">PRELIMINAR · ${esc(c.classification.toUpperCase())}</div><div class="report-block"><h3>01 · Identificação e cenário</h3><p>${esc(lookupReference())}. Vínculo registral não validado.</p><div class="report-keyvalues">${feedbackValue('Zona / macrozona',esc(c.zone||'Pendente')+' / '+esc(c.macrozone||'Pendente'))}${feedbackValue('Produto',esc(activeProduct().name))}${feedbackValue('Pavimentos · inclui térreo',number(c.floors))}${feedbackValue('Área computável',number(c.gross,2)+' m²')}${feedbackValue('Área privativa estimada',number(c.privateArea,2)+' m²')}${feedbackValue('Unidades por área',`${number(c.units)} × ${number(state.unitArea)} m²`)}</div></div>${buildingCapacityReport()}${setbackReport()}${l.geometry?`<div class="report-block"><h3>Geometria cadastrada</h3>${parcelSvg(l.geometry,{envelope:true,envelopeGeometry:c.envelope})}<p>Área ${number(l.area,2)} m²; perímetro ${number(l.geometry.perimeter,2)} m; testada ${number(l.geometry.frontage,2)} m. ${esc(setbackSummary(c.setbackRule))} Área após recuos no térreo: ${number(c.setbackArea,2)} m²; último pavimento: ${number(c.topSetbackArea,2)} m². Perímetro informado, sem validação cadastral ou topográfica.</p></div>`:''}${state.reportGeometry?`<div class="report-block"><h3>02 · Massa conceitual</h3><div class="report-visuals"><div class="report-map">${mapSvg()}</div><canvas class="report-canvas" data-canvas="report" aria-label="Massa conceitual do relatório"></canvas></div></div>`:''}<div class="report-block"><h3>03 · Premissas e limites</h3><p>IA básico ${number(c.baseCa,1)}; máximo ${number(c.maxCa,1)} pela macrozona informada. IA efetivo ${number(c.ca,2)}. TO solicitada ${number(state.to)}%; limite de cenário ${number(c.toMax)}%; TAP ${number(c.permeability)}%.</p><p>${feedbackSource(c.evidence.ia)}. ${feedbackSource(c.evidence.occupation)}.</p><p>OODC: ${esc({pending:'Pendente',informed:'Custo informado; regulamentação pendente',not_required_by_area:'Sem excedente ao básico neste cenário'}[c.outorga.status]||c.outorga.status)}; área excedente ao básico: ${number(c.outorga.excessArea,2)} m². ${esc(c.outorga.message)}</p><p>Núcleo fixo ${number(c.coreArea,1)} m² por pavimento; largura mínima ${number(c.minWidth,2)} m. Estas são premissas da plataforma. Elevador e gerador: ${c.equipment.elevator.required===null?'Pendentes de regra aplicável':c.equipment.elevator.required?'exigidos pelo cenário acima de 4 pavimentos, custos incluídos ou pendentes':'não exigidos por este critério de pavimentos'}. A base normativa específica dos equipamentos aguarda conferência.</p><p>Privativa = laje − núcleo + varanda informada. Balanço padrão: zero; até 0,50 m a partir do 2º pavimento apenas como hipótese condicionada ao COE art. 222. Sem eficiência percentual fixa.</p>${feedbackRows(c)}<p>Terreno plano assumido. A massa não comprova implantação, acessibilidade, ventilação, garagem ou aprovação de altura.</p></div><div class="report-block"><h3>Vagas e limite do produto</h3>${feedbackParking(c)}</div><div class="report-block"><h3>Alternativa H3 · nota B</h3>${feedbackNoteB(c)||'<p>Nota B se destina a H3; uso atual diferente.</p>'}</div>${state.reportAssumptions?`<div class="report-block"><h3>Viabilidade econômica · hipóteses</h3><p>VGV: ${money(c.vgv)}. Custo informado: ${money(state.cost)}/m² construído. Orçamento usa ${number(c.totalBuilt,2)} m²; apoio/garagem adicional exige projeto e não é somado ficticiamente.</p>${feedbackFinancialTable(c)}<p>Não representa recomendação de aquisição. MCMV e financiamento ainda não modelados.</p></div>`:''}<div class="report-block"><h3>Alternativas de produto</h3><table class="compare-table"><thead><tr><th>Produto</th><th>UH por área</th><th>Pav.</th><th>Uso permitido</th></tr></thead><tbody>${productData().map(p=>`<tr><td>${esc(p.name)}</td><td>${number(p.units)}</td><td>${p.floors}</td><td>Pendente · Anexo III, zona × via</td></tr>`).join('')}</tbody></table></div><div class="report-block"><h3>04 · Pendências por item</h3>${feedbackPendings(c)}<p>Cadastro, topografia, alinhamentos, ambiente e patrimônio precisam de confirmação. Sem responsável técnico ou aprovação de órgão competente.</p></div>${state.reportSources?`<div class="report-block"><h3>05 · Origem e rastreabilidade</h3><p>Versão: ${esc(c.engine.version)} · execução: ${esc(c.engine.execution)}. ${esc(c.engine.notice)} Sem homologação jurídica. Fontes e condições constam de cada item.</p></div>`:''}<div class="report-extras">Gerado em ${new Date().toLocaleDateString('pt-BR',{timeZone:'America/Fortaleza'})}. Demonstração de interface; não substitui análise técnica ou certidão urbanística.</div></article><aside class="panel report-options"><h3>Preparar relatório</h3>${[['reportGeometry','Incluir volumetria'],['reportAssumptions','Incluir premissas financeiras'],['reportSources','Incluir versão e rastreabilidade']].map(([k,label])=>`<label><input type="checkbox" data-report="${k}" ${state[k]?'checked':''}>${label}</label>`).join('')}${btn('Imprimir / salvar PDF','download','print','primary wide')}${btn('Exportar cenário JSON','code','export','wide')}<button class="btn wide" type="button" data-engine-retry>Reconsultar cálculo no servidor</button><p class="field-note">Pendências críticas e fontes por item permanecem no relatório.</p></aside></div>`}
function feedbackFinanceView(){const f=state.finance||{},optional=(key,label,value,step='0.01')=>`<div class="form-field"><label for="fin-${key}">${label}</label><input id="fin-${key}" name="${key}" type="number" min="0" max="${key==='annualRate'?100:key.endsWith('Months')||key==='salesStartMonth'?120:1000000000}" step="${step}" value="${esc(value??'')}" placeholder="Pendente"></div>`;return `<div class="notice"><div><strong>Residual a valor presente.</strong> Hipóteses editáveis; valores ausentes permanecem pendentes. Não há cotação de venda fechada nem recomendação de aquisição.</div></div><div class="finance-layout section-space"><form class="panel finance-form" id="finance-form"><div class="panel-kicker">PREMISSAS DO CENÁRIO</div>${financeField('Preço de venda informado','price',state.price,'R$','/m²')}${financeField('Custo direto informado','cost',state.cost,'R$','/m²')}${financeField('Preço proposto do terreno','landPrice',state.landPrice,'R$','')}${financeField('Lucro alvo sobre VGV','profit',state.profit,'','%')}${optional('elevatorCost','Orçamento do elevador (R$)',f.elevatorCost)}${optional('generatorCost','Orçamento do gerador (R$)',f.generatorCost)}${optional('projectsFloor','Piso de projetos (R$)',f.projectsFloor)}${optional('registrationCost','Registro da incorporação (R$)',f.registrationCost)}${optional('outorgaCost','OODC documentada (R$)',f.outorgaCost)}${optional('annualRate','TMA · meta Selic (% a.a.)',f.discount?.annualRate==null?null:Number((f.discount.annualRate*100).toFixed(6)))}<div class="form-field"><label for="fin-discountDate">Data da referência Selic</label><input type="date" id="fin-discountDate" name="discountDate" value="${esc(f.discount?.date||'')}" max="${new Date().toISOString().slice(0,10)}"></div>${optional('constructionMonths','Meses de obra · hipótese',f.constructionMonths??24,'1')}${optional('salesStartMonth','Início das vendas · mês',f.salesStartMonth??12,'1')}${optional('salesMonths','Meses de vendas · hipótese',f.salesMonths??12,'1')}<p class="field-note">Consultar <a href="https://dadosabertos.bcb.gov.br/dataset/432-taxa-de-juros---meta-selic-definida-pelo-copom" target="_blank" rel="noopener noreferrer">Banco Central · SGS 432</a>. Informe taxa e data da mesma referência. RET, ITBI e custos dependem de enquadramento e validação. A área de garagem não é acrescida sem projeto.</p><button class="btn primary wide" type="submit">Atualizar simulação</button></form><div class="finance-results" id="finance-results">${feedbackFinanceResults(calc())}</div></div>`}
function feedbackFinanceResults(c){return `<div class="metrics-grid">${metric('VGV SIMULADO',compact(c.vgv),'Área de UH estimada × preço informado')}${metric('CUSTO SEM TERRENO',compact(c.nonLand),'Custos ausentes impedem o total')}${metric('RESIDUAL A VALOR PRESENTE',compact(c.residual),'Após lucro alvo e ITBI','accent')}</div><div class="panel chart-panel"><h3>Custos e fluxo mensal</h3>${feedbackFinancialTable(c)}${c.financial.cashflow.length?`<details><summary>Fluxo mensal · ${c.financial.cashflow.length} períodos</summary><table class="compare-table"><thead><tr><th>Mês</th><th>Receita</th><th>Despesa</th><th>Lucro alvo</th></tr></thead><tbody>${c.financial.cashflow.map(r=>`<tr><td>${r.month}</td><td>${money(r.revenue)}</td><td>${money(r.expense)}</td><td>${money(r.targetProfit)}</td></tr>`).join('')}</tbody></table></details>`:''}</div><div class="panel chart-panel"><h3>Condições e pendências</h3>${feedbackPendings(c)}</div>`}
function readFeedbackFinance(fd){const f={};for(const key of ['elevatorCost','generatorCost','projectsFloor','registrationCost','outorgaCost']){const v=String(fd.get(key)||'').trim();if(v!=='')f[key]=Number(v)}for(const key of ['constructionMonths','salesStartMonth','salesMonths']){const v=String(fd.get(key)||'').trim();if(v!=='')f[key]=Number(v)}const rate=String(fd.get('annualRate')||'').trim(),date=String(fd.get('discountDate')||'');if(rate!==''&&date)f.discount={annualRate:Number(rate)/100,date,source:'Meta Selic · referência informada pelo usuário, conferir BCB SGS 432'};state.finance=f;}

document.addEventListener('click',event=>{if(event.target.closest('[data-engine-retry]')){EngineResults.retry();render()}});
